import re, csv
from collections import defaultdict

def parse_formula(formula):
    # split into Element+number tokens
    tokens = re.findall(r'([A-Z][a-z]?)(\d*\.?\d*)', formula)
    counts = defaultdict(float)
    for el, n in tokens:
        counts[el] += float(n) if n else 1.0
    total = sum(counts.values())
    fracs = {el: c/total for el,c in counts.items()}
    return dict(counts), fracs, total

elems = ['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']

rows = []
with open('/work/b3_supercon_target.csv') as f:
    r = csv.DictReader(f)
    for row in r:
        counts, fracs, total = parse_formula(row['composition'])
        tc = float(row['target'])
        rows.append((row['composition'], tc, counts, fracs, total))

print('N=', len(rows))
print('\nClosest to 90:')
for comp, tc, counts, fracs, total in sorted(rows, key=lambda x: abs(x[1]-90))[:15]:
    present = {e: round(fracs.get(e,0),6) for e in elems if fracs.get(e,0)>0}
    others = {e: round(fracs[e],6) for e in fracs if e not in elems}
    print(f'Tc={tc:8.3f} {comp:40s} design={present} others={others}')

print('\nObserved max fractions for design elems:')
for e in elems:
    mx = max(r[3].get(e,0) for r in rows)
    print(f'{e:3s} max={mx:.6f}')

print('\nAll samples with Tc in [60,130]:')
for comp, tc, counts, fracs, total in rows:
    if 60 <= tc <= 130:
        present = {e: round(fracs.get(e,0),6) for e in elems if fracs.get(e,0)>0}
        others = {e: round(fracs[e],6) for e in fracs if e not in elems}
        print(f'Tc={tc:8.3f} {comp:45s} tot={total:.3f} design={present} others={others}')
